#include <string>
#include <string_view>
#include <vector>

std::string reversed(std::string_view text)
{
    std::vector<char> stack{};
    for (char c : text)
    {
        stack.push_back(c);
    }
    std::string result{};
    while (!stack.empty())
    {
        result += stack.back();
        stack.pop_back();
    }
    return result;
}

unitTests:
TEST("reverses") { CHECK_EQ(reversed("abc"), "cba"); CHECK_EQ(reversed("stack"), "kcats"); }
TEST("palindromes stay the same") { CHECK_EQ(reversed("level"), "level"); }
TEST("empty and single") { CHECK_EQ(reversed(""), ""); CHECK_EQ(reversed("x"), "x"); }

